SELECT DISTINCT ?prop ?mother WHERE {
  BIND(<http://dbpedia.org/resource/John_I,_Duke_of_Brunswick-Grubenhagen> AS ?person)
  VALUES ?prop { dbp:mother dbo:mother dbo:parent dbp:parent dbp:mother }
  ?person ?prop ?mother .
} LIMIT 50

SELECT ?mother ?motherLabel ?birthDate WHERE {
  BIND(<http://dbpedia.org/resource/Agnes_of_Meissen> AS ?mother)
  OPTIONAL { ?mother dbo:birthDate ?birthDate . }
  OPTIONAL { ?mother dbp:birthDate ?dbpBirth . FILTER(!bound(?birthDate)) BIND(?dbpBirth AS ?birthDate) }
  OPTIONAL { ?mother rdfs:label ?motherLabel . FILTER(lang(?motherLabel) = 'en') }
} LIMIT 10

