output.sparql:
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?mother ?motherLabel ?birthDate ?abstract WHERE {
  BIND(<http://dbpedia.org/resource/John_I,_Duke_of_Brunswick-Grubenhagen> AS ?person)
  ?person dbo:parent ?mother .
  OPTIONAL {
    ?mother dbo:birthDate ?birthDate .
  }
  OPTIONAL {
    ?mother dbp:birthDate ?dbpBirth .
    FILTER(! bound(?birthDate))
    BIND(?dbpBirth AS ?birthDate)
  }
  OPTIONAL {
    ?mother dbo:abstract ?abstract .
    FILTER(lang(?abstract) = 'en')
  }
  OPTIONAL {
    ?mother rdfs:label ?motherLabel .
    FILTER(lang(?motherLabel) = 'en')
  }
}
LIMIT 10

